WITH gaps AS (SELECT *, CASE WHEN LAG(started_at) OVER (PARTITION BY browser ORDER BY started_at ASC, id ASC) IS NULL OR started_at > LAG(started_at) OVER (PARTITION BY browser ORDER BY started_at ASC, id ASC) + INTERVAL 90 DAYS THEN 1 ELSE 0 END AS new_group_flag FROM sessions), sessionized AS (SELECT *, SUM(new_group_flag) OVER (PARTITION BY browser ORDER BY started_at ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_no FROM gaps) SELECT CASE WHEN new_group_flag >= 1 THEN 'LARGE' ELSE 'SMALL' END AS new_group_flag_tier, session_no, SORT_ARRAY(COLLECT_SET(country)) AS country_list, COUNT(DISTINCT country) AS distinct_countries, DENSE_RANK() OVER (PARTITION BY CASE WHEN new_group_flag >= 1 THEN 'LARGE' ELSE 'SMALL' END ORDER BY COUNT(DISTINCT country) DESC) AS distinct_countries_dense_rank FROM sessionized GROUP BY CASE WHEN new_group_flag >= 1 THEN 'LARGE' ELSE 'SMALL' END, session_no HAVING COUNT(DISTINCT country) < 1;
